/**
 * Questions for Kviz, a sixth per topic (60 each: 42 easy, 12 medium, 6 hard): one right answer (`a`) and three wrong ones (`w`).
 * level 1 = easy (most), 2 = a bit harder, 3 = really hard. Each game draws a mix, see src/kviz/logic.ts.
 * Keep options short, the timer is only a few seconds. Facts already in Blef are left out.
 */
export type KvizTopic = 'heroji' | 'gejming' | 'film' | 'zavicaj' | 'istorija' | 'srbija'
export type KvizLevel = 1 | 2 | 3

export interface KvizQuestion {
  id: string
  topic: KvizTopic
  level: KvizLevel
  q: string
  a: string
  w: [string, string, string]
}

export const KVIZ_TOPICS: KvizTopic[] = ['heroji', 'gejming', 'film', 'zavicaj', 'istorija', 'srbija']

